export default [{"id":283,"question":"هناك سؤالٌ من طالبين:أحدهما يقول: يُقام في المعاهد أذانُ صلاة الظهر، فأُصليها أحيانًا وأنا على جنابةٍ؛ لأنه من الصَّعب أمام مئات الطلاب والمُدرسين أن أقول لهم هذا، وليس هذا بتكاسُلٍ مني، فمن بعد الفجر أنام، فأستيقظ متأخِّرًا وأضطر أذهب إلى المعهد، فإذا رجعتُ إلى البيت تطهرتُ وصليتُ.والآخر يقول: في أول الصباح من هذا المُخيم عندما استيقظتُ من النوم وجدتُ نفسي على جنابةٍ، وقد كانت تلك الجنابة السادسة لمدة ستة أيام، فهل هذا مرضٌ أو ماذا؟ وهل عليَّ اغتسالٌ؟ مع العلم أنَّه لا توجد أماكن اغتسال في هذا المكان. وجزاكم الله خيرًا.","title":"حكم من صلى على جنابة حياءً من الناس","answer":"الجواب: أما أن يُصلي وهو جنب فهذا من كبائر الذنوب، ومن المُنكرات العظيمة، وإذا فعله لقلَّة اهتمامٍ وعدم مُبالاةٍ، أو استهزاء بالشرع؛ فشأنه خطيرٌ، قد يكون ردَّةً عن الإسلام -نعوذ بالله تعالى- واستهزاء واحتقارًا للشرع، فالمقصد عظيم جدًّا.\nفالواجب الحذر من هذا، وأن يُصلي وعليه حدثٌ! فكيف إذا كان على جنابةٍ؟!\nفالواجب البدار، وإذا لم يكن هناك محلُّ اغتسالٍ في المكان الذي يذهب إليه فالواجب البدار قبل أن يخرج ولو تأخَّر، قبل أن يخرج من محلِّه يغتسل ولو تأخَّر عن عمله أو درسه أو غير ذلك، هذا مُقدَّمٌ على الدرس، ومقدَّمٌ على العمل، ومقدَّمٌ على كل شيءٍ، ولو خُصم عليه مالٌ فالأمر سهلٌ، فلا يجوز له أبدًا أن يخرج من محلِّه وهو على جنابته، إلا إذا كان في المحل الذي يذهب إليه محلٌّ يغتسل فيه.\nوأدهى من هذا وأكبر وأخطر أن يُصلي في جنابةٍ، هذا منكرٌ عظيمٌ، وفسادٌ كبيرٌ، وتساهلٌ بأمر الله، أما إذا وقع عن سخريةٍ وعن احتقارٍ فهذا شأنه الكفر -نعوذ بالله- قال تعالى: قُلْ أَبِاللَّهِ وَآيَاتِهِ وَرَسُولِهِ كُنْتُمْ تَسْتَهْزِئُونَ ۝ لَا تَعْتَذِرُوا قَدْ كَفَرْتُمْ بَعْدَ إِيمَانِكُمْ [التوبة:65- 66] -نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/4281/حكم-من-صلى-على-جنابة-حياء-من-الناس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0330.mp3","categories":["الغسل","الطهارة لصحة الصلاة"]},{"id":362,"question":"صليتُ الظهر مُعتقدًا أنني على وضوءٍ، ولم أذكر أنني على غير وضوءٍ إلا في اليوم الثاني، ما الحكم؟","title":"حكم من صلَّى يومًا بلا وضوء جهلًا بحدثه","answer":"الجواب:\nالذي صلَّى وهو يظن أنه على وضوءٍ، ثم ذكر بعد يومٍ أو أكثر أنه ليس على وضوءٍ؛ يُعيد الصلاة التي صلَّاها بغير وضوءٍ متى ذكر، ولو بعد شهرٍ، ولو بعد أكثر، متى ذكر أنَّه صلَّى الظهر أو العصر أو المغرب أو العشاء أو الفجر بغير وضوءٍ فإنه يُعيدها وحدها؛ لقول النبي ﷺ: مَن نام عن الصلاة أو نسيها فليُصلها إذا ذكرها، لا كفَّارة لها إلا ذلك، والطَّهارة شرطٌ للصلاة، فإذا صلَّى بغير طهارةٍ أعادها إجماعًا؛ لقول النبي ﷺ: لا تُقبل صلاةٌ بغير طهورٍ، وقوله ﷺ: لا تُقبل صلاةُ أحدكم إذا أحدث حتى يتوضَّأ.","link":"https://binbaz.org.sa/fatwas/4557/حكم-من-صلى-يوما-بلا-وضوء-جهلا-بحدثه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0416.mp3","categories":["الطهارة لصحة الصلاة"]},{"id":739,"question":"إذا أحدث الإمامُ وهو في الصلاة ومن خلفه جماعةٌ، ماذا يفعل آنذاك؟","title":"ماذا يفعل الإمام إذا أحدث في الصلاة؟","answer":"الجواب: إذا أحدث ينفصل ويُقدّم واحدًا منهم يُصلي بالناس، يُكمل بالناس، يتكلم ويقول: تقدَّم يا فلان، يختار من ورائه مَن هو أنسب فيقول: تقدَّم وكمّل بالناس، كمّل صلاة الناس، هذا هو الصواب، يبني على ما مضى، وهو الصواب، وهو الأرجح من قولي العلماء.\nولو كان دخلها على غير وضوءٍ ثم تنبَّه يستخلف مَن يُكمل بهم، وإن استأنف بهم الجديد وصلَّى بهم من أولها فلا بأس، لكن الأفضل والأرجح أن يبني على ما مضى، ولهذا لما طُعن عمرُ  وهو يُصلي بالناس استخلف عبدَالرحمن بن عوف، فقدَّمه يُكمل بالناس صلاة الفجر، ولم يقطعها.\nس: يُقدِّم شخصًا قبل أن يُحْدِث أو إذا أحدث؟\nالشيخ: هذا له حالتان: إحداهما: أن يحسّ بالأمر ويعجز عن الصبر؛ لأنه يشغله، فيُقدِّمه قبل أن يُحدث، وإن أحدث وسبقه الحدثُ -يعني: غلبه الحدثُ وخرج- قدَّمه بعد ذلك، كله واحدٌ، لا حرج.","link":"https://binbaz.org.sa/fatwas/20616/ماذا-يفعل-الامام-اذا-احدث-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0549إذا أحدث الإمام في الصلاة ماذا يفعل ؟ فتاوى المحاضرات.mp3","categories":["الطهارة لصحة الصلاة","صلاة الجماعة"]},{"id":1009,"question":"أشعر بنزول قطرةٍ من البول، فهل يلزمني أن أخرج من الصلاة لأتأكَّد من هذا أم أبني على الأصل وهو الطَّهارة؟","title":"ما يفعل من شك في طهارته أثناء الصلاة؟","answer":"الجواب: عليك أن تبني على الأصل، ولا تلتفت، ولا تخرج؛ لأنَّ الغالب أن هذا يكون من الوساوس والشيطان؛ لأن الشيطان يأتي الإنسانَ في الصلاة ويُخيل إليه أنه خرج منه بولٌ أو ريحٌ، وربما نفخ في مقعدته فأوهمه أنه خرج منه شيءٌ، قال النبيُّ ﷺ: إذا وجد أحدُكم في بطنه شيئًا فأشكل عليه: أخرج منه شيءٌ أم لا، فلا يخرجنَّ من المسجد حتى يسمع صوتًا، أو يجد ريحًا رواه مسلم من حديث أبي هريرة، وفي \"الصحيحين\" من حديث عبدالله بن زيد بن عاصم الأنصاري : أنه شكى للنبي الرجل يجد الشيءَ في الصلاة، شكى إليه بعضُ الصحابة أنه يجد الشيءَ في الصلاة، فقال له النبيُّ: لا ينصرف حتى يسمع صوتًا، أو يجد ريحًا، فلا تنصرف أنت ولا تترك صلاتَك، بل استمرَّ فيها حتى تعلم 100% أنه خرج منك شيءٌ، ما دام عندك شكٌّ ولو 1% لا تخرج، واجعله من الشيطان، لو شككتَ في ريحٍ أو بولٍ أو غير ذلك فالأصل أنه من الشيطان، فاثبت وحارب عدو الله ولا تلتفت إليه.","link":"https://binbaz.org.sa/fatwas/21067/ما-يفعل-من-شك-في-طهارته-اثناء-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0863أشعر بقطرة من البول في الصلاة فهل يلزمني أن أخرج من الصلاة لأتأكد من هذا أم ابني على الأصل؟.mp3","categories":["صلاة الجماعة","الطهارة لصحة الصلاة"]},{"id":1100,"question":"رأيتُ المني في ثوبي بعد عدَّة أيام، فما حكم الصلاة التي أدَّيتُها في تلك الأيام؟","title":"حكم صلاة من رأى الَمنِيَّ في ثوبه بعد أيام","answer":"الجواب:\nإذا رأيتَ المني في ثوبك بعد عدَّة أيام فعليك أن تُعيد الصلاة التي فعلتَها بعد آخر نومة من نوماتك، تُعيد الصلاة، تغتسل وتُعيد الصلاة التي صلَّيتها بعد النوم؛ لأنَّ هذا هو اليقين، اليقين أنه في النومة الأخيرة، والذي قبلها مشكوك فيه، فإذا رأيتَ هذا المني بعد نوم الصُّفرة صباح الاثنين أعد الفجر الذي صليتَه، وإذا رأيتَ هذا المني بعد نوم الظهر أو بعد نومة العصر وصليتَ به المغرب فأعد المغربَ، وهكذا آخر نومة تُعيد الصلاة التي بعدها؛ لأنها هي محلّ الجنابة.","link":"https://binbaz.org.sa/fatwas/21151/حكم-صلاة-من-راى-المني-في-ثوبه-بعد-ايام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0947رأيتُ المني في ثوبي بعد عدة أيام فما حكم الصلاة التي أديتها في تلك الأيام؟ ابن باز.mp3","categories":["صلاة الجماعة","الطهارة لصحة الصلاة"]},{"id":1102,"question":"بعض الناس يُصلون بلا وضوءٍ، فما حكم صلاتهم؟","title":"ما حكم مَن صلى بغير وضوء؟","answer":"الجواب:\nإن كان مُتعمِّدًا فقد أتى مُنكرًا عظيمًا، وإذا كان مُستهزئًا كفر، إن كان جاهلًا فقد أتى مُنكرًا عظيمًا، صلاته باطلة، إن كان جاهلًا: ما درى عن الشرع، ولا عاش بين المسلمين، فهذا يُعلَّم ويُعيد الصلاة التي صلَّاها بغير وضوءٍ. نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/21149/ما-حكم-من-صلى-بغير-وضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0945ما حكم الصلاة بلا وضوء؟ ابن بازفتاوى المحاضرات.mp3","categories":["صلاة الجماعة","الطهارة لصحة الصلاة"]},{"id":2760,"question":"إذا شك إنسان في طهارة الحصير أو الفراش؟","title":"حكم الشك في طهارة الحصير أو الفراش","answer":"الجواب: الأصل الطهارة، هذا من الشيطان.","link":"https://binbaz.org.sa/fatwas/22908/حكم-الشك-في-طهارة-الحصير-او-الفراش","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الشك في طهارة الحصير أو الفراش.mp3","categories":["صلاة الجماعة","الطهارة لصحة الصلاة"]},{"id":2789,"question":"رجل احتلم فلما استيقظ كان وقت الفجر ضيقًا بحيث أنه يدرك الصلاة، فهل له أن يدخل الوضوء الطهارة الصغرى في الكبرى أو هو خاص بالجنابة؟","title":"حكم مَنْ احتلم وكان وقت الفجر ضيقاً","answer":"الجواب: لا يدخله، يعني على جنابة هو؟\nس: احتلم نعم.\nالشيخ: ينويهما جميعا ويجزئه، وإن توضأ أفضل ثم اغتسل مثل فعل النبي ﷺ يكون أفضل.\nس: بعض العلماء اشترطوا المضمضة؟\nالشيخ: المضمضة والاستنشاق للجميع، للوضوء والغسل، للجميع إذا نواهما جميعا دخل فيه.\nس: يعني يكفيه أن يفيض الماء على رأسه ثلاثًا؟\nالشيخ: على جميع بدنه بنية الحدثين.\nس: لكن إذا قيل بوجوب المضمضة والاستنشاق؟\nالشيخ: لا بد في الغسل والوضوء جميعًا.","link":"https://binbaz.org.sa/fatwas/22937/حكم-من-احتلم-وكان-وقت-الفجر-ضيقا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/احتلم واستيقظ كان وقت الفجر ضيقاً.mp3","categories":["صلاة الجماعة","الطهارة لصحة الصلاة"]},{"id":3976,"question":"حمل الصغار في الصلاة وهم لا يتحرزون عن البول؟","title":"ما حكم حمل الصغار في الصلاة؟","answer":"الجواب: الأصل السلامة، محمول على السلامة، هذا هو الأصل، فإذا عرف أنها نجسة لا يحملها.","link":"https://binbaz.org.sa/fatwas/24204/ما-حكم-حمل-الصغار-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حمل الصغار في الصلاة وهم لا يتحرزون عن البول.mp3","categories":["صلاة الجماعة","الطهارة لصحة الصلاة"]},{"id":4952,"question":"إذا كان مسجونًا في مكان نجس كيف يفعل في صلاته؟","title":"كيف يصلي المسجون في مكان نجس؟","answer":"الجواب: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن: 16]، يصلي على حسب حاله، ولو في المكان النجس تصح صلاته وَقَدْ فَصَّلَ لَكُمْ مَا حَرَّمَ عَلَيْكُمْ إِلَّا مَا اضْطُرِرْتُمْ إِلَيْهِ.. [الأنعام: 119].","link":"https://binbaz.org.sa/fatwas/27523/كيف-يصلي-المسجون-في-مكان-نجس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/كيف يصلي المسجون في مكان نجس؟.mp3","categories":["صلاة الجماعة","الطهارة لصحة الصلاة"]},{"id":5559,"question":"مسألة الوضوء من ماء البرادات، قلتم مرةً أنه يُعيد الصلاة، وقلتم مرة أنه لا يُعيد الصلاة؟","title":"حكم صلاة من توضأ من ماء البرادات الموقوفة","answer":"الجواب: مسألة خلافٍ بين أهل العلم في المغصوب: جماعة من أهل العلم يقولون: يُعيد، وجماعة يقولون: المغصوب ليس خاصًّا بالماء، عام، لا يُستعمل المغصوب بالكلية، لكن لو صلَّى في الأرض المغصوبة، أو توضأ بالمغصوب صحَّت، ولكنه آثم؛ لأنَّ التحريم ليس خاصًّا بالصلاة، عام، ليس له أن يستعمل الماء الموقوف في غير ما وُقف فيه، وليس له أن يستعمل الأرض التي لم يُؤذن له فيها: لا يجلس فيها، ولا ينام فيها، ولا يُصلي فيها، فلما كان النَّهي عامًّا صحَّت الصلاة بهذا الشيء العام، بخلاف الخاصّ، الخاصّ يختص بما اختصَّ به، بالصلاة أو غيرها، مثل: كون الإنسان يُفطر بالأكل والشرب ونحو ذلك؛ لأنَّ الصائم ممنوع من ذلك، بخلاف ما لو ظلم أحدًا، أو ضرب أحدًا، أو دخل بيت أحدٍ؛ ما يُفطر بذلك، وإن كان عاصيًا؛ لأنَّ هذا نهي عام، وإنما الشيء الخاصّ ما يتعلق بأكله وشربه، وهكذا مسألة الماء المغصوب، والأرض المغصوبة، ولعلَّ هذا أقرب إن شاء الله؛ لأنَّ النَّهي عام، وإن أعاد احتياطًا وخروجًا من الخلاف؛ فحسن إن شاء الله. س: إذًا تصح مع الإثم؟ ج: مع الإثم، نعم، مثل: مَن صلَّى في ثوبٍ مغصوبٍ، أو اشتراه بعقدٍ فاسدٍ، المقصود بثوبٍ مغصوبٍ واضح، فالصلاة صحيحة؛ لأنَّ غصبه ما هو خاصّ بالصلاة، منكر عليه مطلقًا، ولو في غير الصَّلاة.[1]","link":"https://binbaz.org.sa/fatwas/31512/حكم-صلاة-من-توضا-من-ماء-البرادات-الموقوفة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/zad almaad 023.mp3","categories":["صلاة الجماعة","الطهارة لصحة الصلاة"]},{"id":5792,"question":"يا شيخ، عفا الله عنك، صليت المغرب، وذهبت في سيارة أنا وربع معي، وجاء علينا وقت المغرب، فقلت لهم وقفوا نصلي، فوقفنا نصلي، وصليت، وبعد أن صليت تذكرت أني لست على وضوء، وبعد أن رجعت إلى البيت توضأت وصليت، فقال لي أناس: لا تصلي حتى يأتي المغرب عليك، وصلي، وأنا عصيتهم وصليت، وقدمت المغرب؟","title":"من صلى ثم تذكر بعدها أنه على غير طهارة","answer":"الجواب: أحسنت وأخطؤوا، من قال لك: أن ما تصلي المغرب إلا في المغرب الآخر، وما بين الوقتين صلاة، فهذا غلط، فإذا صليت مع الناس، ثم تبين لك... تعيدها في الحال، تتوضأ، وتعيدها في الحال، النبي ﷺ قال: من نام عن الصلاة، أو نسيها فليصلها إذا ذكرها، لا كفارة لها إلا ذلك هذا فرض، والله قال: وَأَقِمِ الصَّلَاةَ لِذِكْرِي [طه:14].  فالحاصل: أن الإنسان إذا صلى وهو على حدث، ثم تنبه؛ يبادر بالصلاة، يتوضأ ويبادر، أو استيقظ وقد خرج الوقت يبادر، ثم يصلي، ولا يؤخر ولا يؤجل. لكن المسافرين إذا حضر وقت المغرب، وهم في السيارة مسافرون، الأفضل ما ينزلون، الأفضل أن يؤجلوا المغرب مع العشاء هذا الأفضل، كان النبي ﷺ إذا ارتحل قبل دخول المغرب أجل المغرب مع العشاء، وإذا ارتحل قبل الزوال أجل الظهر مع العصر، يجمعها مع العصر.  وهكذا المغرب إذا ارتحل إنسان من مكانه على السيارة، أو على الدابة قبل الغروب يؤجل صلاة المغرب، ما ينزلون ويصلوا المغرب لا، يأجلها مع العشاء هذا السنة.","link":"https://binbaz.org.sa/fatwas/1118/من-صلى-ثم-تذكر-بعدها-انه-على-غير-طهارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_125.mp3","categories":["الطواف بالبيت","السعي","الطهارة لصحة الصلاة"]},{"id":6310,"question":"هل يجوز لرجل كان عليه غسل جنابة أن يتيمم، ويترك الصلاة، ويوجد الماء، مع العلم أنه إذا اغتسل؛ سوف تفوته صلاة الجماعة، ولم يفته وقت الصلاة؟","title":"حكم تيمم الجنب مع وجود الماء لكي يدرك الجماعة","answer":"الجواب: إذا كان عليه غسل الجنابة؛ يغتسل، ولا يتيمم، ولا يجوز له التيمم، بل يبطل التيمم إذا كان الماء موجودًا، وهو يقدر على استعماله، فيلزمه الغسل، ولو فاتته الجماعة، لو قدر أنه كان .. إذا اغتسل تفوته الجماعة، وإذا تيمم لا تفوته الجماعة لا، لا يتيمم، يغتسل بالماء، ويصلي، ولو في بيته إن ما تيسر له الجماعة. ولكن يجب عليه أن يجعل هناك وقتًا واسعًا، أو يضبط الساعة على وقت واسع، أو يقول للذين يوقظونه قبل الفجر حتى يتمكن من الغسل، والصلاة مع الجماعة، لا يتساهل، والناس -بحمد الله- عندهم ساعات، الآن تيسرت الساعات، يوقتها على الوقت المناسب؛ حتى يقوم في وقت مبكر، ويغتسل على هدوء، ويصلي ما كتب الله له، ثم يتوجه لصلاة الجماعة، هذا الواجب عليه، نسأل الله السلامة.","link":"https://binbaz.org.sa/fatwas/1871/حكم-تيمم-الجنب-مع-وجود-الماء-لكي-يدرك-الجماعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_661.mp3","categories":["الطواف بالبيت","السعي","الطهارة لصحة الصلاة"]},{"id":6330,"question":"هل يجوز لرجل كان عليه غسل جنابة أن يتيمم، ويترك الصلاة، ويوجد الماء، مع العلم أنه إذا اغتسل؛ سوف تفوته صلاة الجماعة، ولم يفته وقت الصلاة؟","title":"حكم تيمم الجنب مع وجود الماء لكي يدرك الجماعة","answer":"الجواب: إذا كان عليه غسل الجنابة؛ يغتسل، ولا يتيمم، ولا يجوز له التيمم، بل يبطل التيمم إذا كان الماء موجودًا، وهو يقدر على استعماله، فيلزمه الغسل، ولو فاتته الجماعة، لو قدر أنه كان .. إذا اغتسل تفوته الجماعة، وإذا تيمم لا تفوته الجماعة لا، لا يتيمم، يغتسل بالماء، ويصلي، ولو في بيته إن ما تيسر له الجماعة. ولكن يجب عليه أن يجعل هناك وقتًا واسعًا، أو يضبط الساعة على وقت واسع، أو يقول للذين يوقظونه قبل الفجر حتى يتمكن من الغسل، والصلاة مع الجماعة، لا يتساهل، والناس -بحمد الله- عندهم ساعات، الآن تيسرت الساعات، يوقتها على الوقت المناسب؛ حتى يقوم في وقت مبكر، ويغتسل على هدوء، ويصلي ما كتب الله له، ثم يتوجه لصلاة الجماعة، هذا الواجب عليه، نسأل الله السلامة.","link":"https://binbaz.org.sa/fatwas/1871/حكم-تيمم-الجنب-مع-وجود-الماء-لكي-يدرك-الجماعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_661.mp3","categories":["الطواف بالبيت","السعي","الطهارة لصحة الصلاة"]},{"id":7674,"question":"ونبدأ يا سماحة الشيخ برسالة المستمع فهد عبد الوهاب الخميس من الزلفي، يقول: إلى فضيلة الشيخ: عبد العزيز بن عبد الله بن باز ، السلام عليكم ورحمة الله وبركاته، حفظكم الله، آمين: إنسان صلى جماعة فلما خرج من المسجد وجد معه منديل فيه دم من بشرته فقذفه ورجع يعيد الصلاة فوجد جماعةً فصلى معهم، هل إذا حصل مثل هذا عليه إعادة الصلاة أم لا؟ أفيدونا جزاكم الله خير، ولكم منا جزيل الشكر، ونرجو لكم التوفيق إن شاء الله تعالى.","title":"حكم صلاة من كان حامل النجاسة","answer":"الجواب: الحمد لله، والصلاة والسلام على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد:\nإذا صلى الإنسان رجلاً كان أو امرأة، ثم بعد الفراغ وجد في منديله دماً، أو في ثوبه دماً، أو في سراويله دماً، أو غير ذلك من النجاسات، فإن الصواب: أنه لا يعيد الصلاة، صلاته تجزي وتصح، هذا هو الصواب من أقوال العلماء، أنه لا إعادة عليه وصلاته صحيحة، وإن كان قد علم ذلك سابقاً ثم نسيه حتى صلى، كذلك صلاته صحيحة، وعليه أن يبادر بغسل ذلك، وتنظيف ثوبه من ذلك، والحجة في ذلك أن الرسول ﷺ صلى وعليه نعلان فأخبره جبرائيل أن فيهما أذى، فخلعهما ولم يعد أول الصلاة، فدل ذلك على أنه لو كملها ما عاد، فالمقصود أن من كان في ثوبه نجاسة ما علم بها حتى فرغ، أو في سراويله، أو في إزاره، أو في عمامته، أو في منديله، أو في خفه ونعله ولم يعلم حتى فرغ فصلاته صحيحة، هذا هو الصواب الذي عليه المحققون من أهل العلم، ولا إعادة عليه. نعم.\nلكن هنا شيء آخر قد يظنه بعض الناس مثل هذا، وهو إذا صلى يحسب أنه متوضئ، أو يحسب أنه قد تطهر من الجنابة، ثم بان أن عليه جنابة، أو أنه ما توضأ هذا يعيد بإجماع المسلمين، هذا عليه أن يعيد؛ لأنه صلى بغير طهارة بالحدث، هذا ما هو من جنس النجاسة، هذا إذا صلى مثلاً يحسب أنه على وضوء، أو يحسب أنه قد اغتسل من الجنابة، ثم لما صلى ذكر أن عليه جنابة، أو أنه ما توضأ أنه محدث، هذا عليه أن يتوضأ وأن يغتسل من الجنابة إذا كان عليه جنابة ثم يعيد صلاته، وإن كان إمام لا يعيد المأمومون، إذا ما درى إلا بعد الصلاة يعيد هو أما المأمومون فلا يعيدون إذا كان ما انتبه إلا بعد الصلاة، هذه مسألة قد تخفى على بعض الناس، وقد تشتبه بمسألة النجاسة والحكم يختلف. نعم.","link":"https://binbaz.org.sa/fatwas/4873/حكم-صلاة-من-كان-حامل-النجاسة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_040/04001.mp3","categories":["النجاسات وإزالتها","الطهارة لصحة الصلاة","قضايا المرأة"]},{"id":7710,"question":"سؤاله الثاني يقول: كيف يصلي السجين عندما يتعذر عليه الحصول على الماء، وكيف يتطهر من الجنابة إذا أصابته؟","title":"كيفية صلاة فاقد الطهورين أو أحدهما","answer":"الجواب: السجين له أحوال: إن كان يستطيع أنه يتوضأ ويستنجي بالحجارة فالحمد لله، وإن كان ما يستطيع فإنه يتيمم ولا حرج في ذلك، فالمقصود أن السجين فيه تفصيل. \nالمقدم: إذاً يستطيع أن يتطهر وذلك على قدر استطاعته. \nالشيخ: لا بأس، إذا كان السجين عنده ماء وتمكن من الماء يتوضأ من الحدث الأصغر، ويغتسل من الجنابة كغيره من الناس، وإن كان غير ممكن ليس عنده ماء ولا يتمكن فإنه يتطهر من النجاسات بالمناديل ونحوها، يتمسح بالمنديل ثلاث مرات فأكثر، مناديل أو بحجر أو بلبن أو بغير هذا من الجامدات النواشف الطاهرات حتى ينقي المحل.. ينقي الدبر والذكر من أثر البول والغائط ثلاث مرات فأكثر، لا ينقص عن ثلاث، يعني: وتراً، ثلاث أو أكثر حتى ينقي المحل، ثم يتوضأ وضوء الصلاة، يتمسح وضوء الصلاة إذا حصل على الماء ويغسل من الجنابة إذا كان عليه جنابة بالماء، فإن لم يتيسر له الماء وحيل بينه وبين الماء تيمم بالتراب، ضرب الأرض بيديه ومسح وجهه وكفيه بالتراب، ناوياً عن الجنابة وناوياً عن الحدث الأصغر، ويكفي ذلك، يكفيه تيمم واحد عنهما جميعاً عن الحدث الأصغر والأكبر جميعاً. \nالمقدم: طيب لو لم يتمكن أيضاً من التراب؟\nالشيخ: إذا ما تمكن من ذلك أجزأ، صلى على حسب حاله فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] بلا ماء ولا تيمم فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16].","link":"https://binbaz.org.sa/fatwas/4909/كيفية-صلاة-فاقد-الطهورين-او-احدهما ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_030/03004.mp3","categories":["الطهارة لصحة الصلاة"]},{"id":10278,"question":"آخر سؤالٍ له يقول فيه: إن له إخوةً صغارًا، وإذا صلى في البيت تأخذه الوساوس خشية أن يكون المكان الذي صلى فيه غير طاهرٍ.توجيهكم سماحة الشيخ، وكيف يتصرف؟ جزاكم الله خيرًا.","title":"حكم الصلاة على فرش البيت مع وجود الصغار","answer":"الجواب: الأصل في الأرض الطهارة، والأصل في الفرش الطهارة، هذا هو الأصل، فلا مانع أن تصلي على الأرض والفراش، إلا إذا علمت يقينًا أنه أصابته نجاسةٌ، وإلا فالأصل الطهارة، ولو عندك بزورٌ، ولو أن عندك صبيةً صغارًا الأصل الطهارة في الأرض والفراش، ولا حرج أن تصلي النافلة على هذا الفراش، أو على هذه الأرض، أما الفريضة فعليك أن تصلي مع الناس في المساجد، أن تصلي الجماعة مع الناس، لكن إذا اتخذت مُصلًّى يكون أحسن، تتخذ مُصلًّى لك معروفًا في بعض بيتك تصلي فيه النوافل، أو يكون سجادةً خاصةً تصلي عليها، تخصها، تحفظها لك، عندما تصلي تهجدك أو النوافل؛ حتى يطمئن قلبك إلى أن مُصلاك طاهرٌ، وإلا فالأصل الطهارة، والحمد لله. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8452/حكم-الصلاة-على-فرش-البيت-مع-وجود-الصغار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_311/31108.mp3","categories":["الطهارة لصحة الصلاة"]},{"id":10842,"question":"من مكة المكرمة المستمع (م. ع. ق) بعث برسالة ضمنها ثلاثة أسئلة، في أحد أسئلته يقول: إنه مصاب بسلس البول كيف تنصحونه سماحة الشيخ ليؤدي صلواته على الوجه الأكمل؟","title":"كيف يصلي من به سلس البول؟","answer":"الجواب:  صاحب السلس مثل المرأة صاحبة الاستحاضة، الواجب عليه -كما بين أهل العلم- أنه يتوضأ لكل صلاة، إذا دخل الوقت يتوضأ ويصلي مع الناس -والحمد لله- يتحفظ بشيء من القطن، أو غيره على ذكره حتى لا يتأذى بالبول في ثيابه وبدنه، كما أن المستحاضة تتلجم وتتحفظ بشيء، وتصلي الصلوات في أوقاتها، وتتوضأ إذا دخل الوقت، ولهذا قال ﷺ للمستحاضة: توضئي لوقت كل صلاة، فصاحب السلس ومثله صاحب الريح الذي تخرج منه الريح دائمًا ما يستطيع البقاء إلى وقت يؤدي فيه الصلاة فإنه يصلي على حسب حاله، يتوضأ إذا دخل الوقت، ويصلي مع الناس، ولو خرج منه الريح، أو خرج منه البول، كما تصلي المستحاضة، ولو خرج منها الدم، لكن يتوضأ بعد دخول الوقت ما دام الحدث دائمًا، نعم.  المقدم: المهم أنكم تنصحون كلًا من صاحب السلس، وصاحبة الاستحاضة بالتحفظ عند تأدية الصلاة. الشيخ: نعم، دائمًا تحفظ دائمًا حتى يكون ذلك أسلم للبدن والثياب.","link":"https://binbaz.org.sa/fatwas/9019/كيف-يصلي-من-به-سلس-البول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_355/35512.mp3","categories":["الطهارة لصحة الصلاة"]},{"id":11093,"question":"هذا السائل حسن حاج من سوريا، يقول: ما حكم من صلى الصلوات الخمس في وضوء واحد؟ جزاكم الله خيرًا.","title":"حكم صلاة الخمسة فروض بوضوء واحد","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فلا حرج على من صلى الصلوات الخمس بوضوء واحد؛ لأن المقصود أن يؤديها على طهارة، فإذا كان على طهارة فلا حرج، فلو صلى الفجر بالطهارة، وبقي على طهارته الظهر والعصر والمغرب والعشاء صحت، وصح عن النبي ﷺ: أنه صلى الصلوات الخمس يوم الفتح بوضوء واحد، فسأله عمر عن ذلك، فقال: عمدًا فعلته اللهم صل عليه وسلم، يعني: للتعليم، لتعليم الناس. نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/9271/حكم-صلاة-الخمسة-فروض-بوضوء-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_290/29001.mp3","categories":["الطهارة لصحة الصلاة"]},{"id":11196,"question":"مريض يصلي ولا زال يصلي بالتيمم وملابسه وفرشه غير طاهرة؛ لعدم استطاعته الطهارة عند كل صلاة أفتونا مأجورين في حاله؟","title":"حكم صلاة المريض في ملابس غير طاهرة","answer":"الجواب: الواجب عليه أن يطهر ثيابه ومحل صلاته كل وقت، فإذا لم يستطع صلى على حسب حاله، إذا كان ما عنده أحد يطهرها ولا يستطيع هو، فالله يقول: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] يصلي على حسب حاله، والتيمم يجوز له إذا كان عاجزًا عن الماء، إذا كان لا يستطيع أن يستعمل الماء يضره الماء، فإنه يتيمم ويكفيه التيمم والحمد لله. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9367/حكم-صلاة-المريض-في-ملابس-غير-طاهرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_372/37212.mp3","categories":["صلاة المريض","الطهارة لصحة الصلاة"]},{"id":11297,"question":"يقول: هل علي إثم في ترك الوضوء خوفًا من فوات الوقت أم لابد أن أتوضأ؟ جزاكم الله خيرًا. الشيخ: أعد أعد .المقدم: هل علي إثم في ترك الوضوء خوفًا من فوات الوقت؟ أم لابد أن أتوضأ؟","title":"حكم الاكتفاء بالتيمم خوفاً من فوات وقت الصلاة","answer":"الجواب:  هذا فيه تفصيل: إن كنت قمت من النوم غلبك النوم وقمت؛ توضأ ولو خرج الوقت، أو ناسٍ ثم انتبهت؛ توضأ ولو خرج الوقت، الوقت هو وقت الاستيقاظ ووقت انتباهك، لقول النبي ﷺ: من نام عن الصلاة أو نسيها فليصلها إذا ذكرها لا كفارة لها إلا ذلك. أما إن كنت متساهلًا ما عندك نسيان ولا نوم: فالواجب عليك أن تصليها في وقتها، ولو بالتيمم إذا ضاق الوقت، ولو بالتيمم، ليس لك التأخير؛ لأنك حينئذ ظالم بهذا التأخير معتدٍ، فالواجب عليك البدار بأن تصليها قبل خروج الوقت ولو بالتيمم، نسأل الله السلامة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9478/حكم-الاكتفاء-بالتيمم-خوفا-من-فوات-وقت-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_376/37610.mp3","categories":["الطهارة لصحة الصلاة"]},{"id":11302,"question":"يقول: هل علي إثم في ترك الوضوء خوفًا من فوات الوقت أم لابد أن أتوضأ؟ جزاكم الله خيرًا. الشيخ: أعد أعد .المقدم: هل علي إثم في ترك الوضوء خوفًا من فوات الوقت؟ أم لابد أن أتوضأ؟","title":"حكم الاكتفاء بالتيمم خوفاً من فوات وقت الصلاة","answer":"الجواب:  هذا فيه تفصيل: إن كنت قمت من النوم غلبك النوم وقمت؛ توضأ ولو خرج الوقت، أو ناسٍ ثم انتبهت؛ توضأ ولو خرج الوقت، الوقت هو وقت الاستيقاظ ووقت انتباهك، لقول النبي ﷺ: من نام عن الصلاة أو نسيها فليصلها إذا ذكرها لا كفارة لها إلا ذلك. أما إن كنت متساهلًا ما عندك نسيان ولا نوم: فالواجب عليك أن تصليها في وقتها، ولو بالتيمم إذا ضاق الوقت، ولو بالتيمم، ليس لك التأخير؛ لأنك حينئذ ظالم بهذا التأخير معتدٍ، فالواجب عليك البدار بأن تصليها قبل خروج الوقت ولو بالتيمم، نسأل الله السلامة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9478/حكم-الاكتفاء-بالتيمم-خوفا-من-فوات-وقت-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_376/37610.mp3","categories":["الطهارة لصحة الصلاة"]},{"id":11570,"question":"بعد هذا رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات تقول: أختكم في الله (ح. ع. ع. الجهني)، أختنا تقول في أحد أسئلة لها: هل من صلى وهو يعتقد أنه على وضوء، ثم تبين له أنه صلى بدون وضوء، هل تصح صلاته؟ أم لابد عليه من الإعادة؟ جزاكم الله خيرًا.","title":"حكم من صلى ثم تبين له أنه على غير وضوء","answer":"الجواب:  لابد من القضاء، من صلى وهو يظن أنه على وضوء، ثم تبين له أنه ليس على وضوء؛ يعيد؛ لقول النبي ﷺ: لا تقبل صلاة بغير طهور وقوله -عليه الصلاة والسلام-: لا تقبل صلاة أحدكم إذا أحدث حتى يتوضأ هذا بإجماع المسلمين، هذا محل إجماع بين المسلمين أن الإنسان إذا صلى، ثم اتضح له أنه على غير وضوء؛ فإنه يعيد الصلاة، يتوضأ ويعيد الصلاة. بخلاف من صلى وفي ثوبه نجاسة، ولم يعلم إلا بعد الصلاة؛ هذا لا يعيد على الصحيح، لو صلى في ثوبه أو سراويله أو بشته أو شيء فيه نجاسة، لكن لم يعلم حتى فرغ؛ فالصواب: أن صلاته صحيحة، ولا تلزمه الإعادة، ولو كان يعلمها ثم نسيها.  أما الذي صلى وهو محدث، يحسب أنه طاهر، ثم تبين له أنه محدث؛ هذا تلزمه الإعادة؛ لأن شرط الصلاة الطهارة، ولم يأت بذلك، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9753/حكم-من-صلى-ثم-تبين-له-انه-على-غير-وضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_386/38603.mp3","categories":["الطهارة لصحة الصلاة"]},{"id":11973,"question":"أسأل سماحتكم عن صلاة صليتها، وتذكرت أنني صليتها بدون وضوء، كيف أتصرف؟","title":"حكم من صلى بغير وضوء ناسيًا فتذكر","answer":"الجواب:  عليك أن تقضيها، متى ذكرت ذلك عليك أن تقضيها، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10158/حكم-من-صلى-بغير-وضوء-ناسيا-فتذكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_429/42914.mp3","categories":["الطهارة لصحة الصلاة"]},{"id":12016,"question":"بعد هذا رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين رمز إلى اسمه بالحروف (ن. س) أخونا يقول: إنني مصاب بسلس، وأحيانًا ينزل مني ماء بقدر قطرة أو قطرتين، وأحيانًا أيضًا أصلي بالناس إمامًا، فهل يجوز لي ذلك، أو لا؟ جزاكم الله خيرًا.","title":"حكم إمامة من به سلس بول وصفة تطهره","answer":"الجواب:  إذا كان السلس مستمرًا معك، وهو خروج الماء -يعني البول- فلا تتوضأ إلا إذا دخل الوقت، كلما دخل الوقت؛ توضأ، وإذا توضأت تصلي بهذا الوضوء ما دمت في الوقت، مثل المستحاضة التي أمرها النبي ﷺ أن تتوضأ لكل صلاة؛ لأن حدثها دائم، وهو خروج الدم. فهكذا من كان بوله مستمرًا معه؛ فإنه يتوضأ لكل صلاة، يعني: إذا دخل الوقت، فيتوضأ للعصر إذا دخل وقتها، ويصلي حتى يخرج الوقت، ويقرأ القرآن من المصحف، وهكذا يتوضأ للمغرب ويصلي حتى يغيب الشفق، وهكذا بعد العشاء يتوضأ حتى يذهب الوقت. المقصود: أن لكل وقت وضوءًا لصاحب السلس، والأحوط لك ألا تصلي بالناس إمامًا؛ لأن جمعًا من أهل العلم يرون أنه لا يصلي صاحب السلس إمامًا بالناس، وإن صليت؛ تكون الصلاة صحيحة -إن شاء الله- على الصحيح، لكن ترك ذلك أولى، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10201/حكم-امامة-من-به-سلس-بول-وصفة-تطهره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_432/43207.mp3","categories":["الطهارة لصحة الصلاة","صلاة الجماعة"]},{"id":12082,"question":"يقول: أعمل راعٍ للغنم، وأسكن في منطقة بعيدة تكثر فيها الحشرات الزاحفة، وحينئذٍ أضطر للصلاة على السرير، فهل يجوز أن أفعل ذلك، أو لا؟","title":"حكم الصلاة على السرير","answer":"الجواب:  لا حرج في ذلك، والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10267/حكم-الصلاة-على-السرير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_435/43515.mp3","categories":["الطهارة لصحة الصلاة"]},{"id":12550,"question":"يسأل أخونا سؤالًا آخر ويقول: تعرضت لحادث سيارة، وأصبحت الآن مقعدًا لا أتحرك إلا بواسطة العربية، ولا أتحكم في السبيلين، ولا أستطيع السيطرة عليهما، كيف تنصحونني في الوضوء، أو التيمم؟ جزاكم الله خيرًا.","title":"كيفية طهارة من لا يستطيع التحكم في الخارج من السبيلين","answer":"الجواب:  مثلك مثل صاحب السلس والمستحاضة، عليك أن تتوضأ لوقت كل صلاة، والحمد لله، إذا دخل وقت الصلاة؛ تستنجي، وتتوضأ وضوء الصلاة، وتصلي في الوقت حتى يجيء الوقت الآخر، ولو خرج شيء منك فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] هكذا كل وقت، تستنجي وتتوضأ وتصلي على حسب حالك، وتقرأ من المصحف، ولا حرج عليك في ذلك؛ لأنك معذور، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10757/كيفية-طهارة-من-لا-يستطيع-التحكم-في-الخارج-من-السبيلين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_410/41003.mp3","categories":["صلاة المريض","الطهارة لصحة الصلاة"]},{"id":13000,"question":"السائلة (ع. ن) من الرياض تقول: قضيتي الأولى ما يلي: تذكر بأنها شابة ومتزوجة، وعندها طفلين -تحمد الله على ذلك- تقول: المشكلة -يا سماحة الشيخ- هو أنني عندما كنت في الأيام الأولى من زواجي لم أكن أغتسل من الجنابة بسبب الجهل في ذلك؛ لأنني كنت أظن بأن الاغتسال خاص بالرجال فقط، دون النساء، وعندما علمت بأن المرأة يجب عليها الاغتسال؛ ندمت ندمًا كثيرًا على ما كان من جهلي، وأنا الآن لا أدري ما عدد الصلوات التي كنت أصليها، وأنا علي الجنابة، وقد جلست على تلك الفترة ما يقارب من شهرين تقريبًا، ماذا علي يا -سماحة الشيخ- تجاه تلك الصلوات؟","title":"حكم من كان يصلي على جنابة جهلاً منه","answer":"الجواب:  ليس عليك إلا التوبة، التوبة تجب ما قبلها، يقول النبي ﷺ: الإسلام يجب ما قبله، والتوبة تجب ما كان قبلها والحمد لله، وإن قضيت الصلوات بالظن؛ فهو طيب، وحسن؛ خروجًا من الخلاف، إن قضيت ما تظنين أنك صليتها، وعليك الجنابة؛ فهذا حسن؛ من باب الخروج من الخلاف، وإلا فأنت تنفعك التوبة، ويكفيك التوبة، والحمد لله؛ لأجل جهلك، وعدم عنايتك بالسؤال، فأنت قد فرطت، وأسأت؛ فعليك التوبة إلى الله، وترك الصلاة كفر، والكافر توبته تكفي، إذا تاب الكافر؛ ما عليه قضاء، نسأل الله السلامة، نعم، والذي يصلي وعليه جنابة حكمه حكم الذي ما يصلي، نسأل الله العافية، نعم. المقدم: نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/11217/حكم-من-كان-يصلي-على-جنابة-جهلا-منه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_504/50413.mp3","categories":["الطهارة لصحة الصلاة","النجاسات وإزالتها"]},{"id":13222,"question":"تقول في آخر أسئلتها إذا توضأت المرأة لصلاة الضحى فهل يجوز لها أن تصلي الظهر وهي على نفس الوضوء؟","title":"حكم من صلى عدة صلوات بوضوء واحد","answer":"الجواب:  نعم، من توضأ الضحى لصلاة الضحى، أو ليقرأ؛ فله أن يصلي به الظهر إذا جاء وقت الظهر وهو على طهارة، ويصلي به العصر أيضًا، لو توضأ الضحى، صلاة الضحى، وبقي على طهارته؛ صلى بها الظهر والعصر حتى ولو المغرب، لو بقي على طهارته؛ صلى بها المغرب أيضًا. ثبت عنه ﷺ: أنه صلى يوم الفتح الصلوات الخمس بوضوء واحد -عليه الصلاة والسلام- قال: عمدًا فعلت هذا ليعلم الناس -عليه الصلاة والسلام- أن الإنسان إذا كان على طهارة يصلي الأوقات الكثيرة، والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11507/حكم-من-صلى-عدة-صلوات-بوضوء-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_520/52012.mp3","categories":["الطهارة لصحة الصلاة"]},{"id":13356,"question":"هل تجوز الصلاة إذا كان الإنسان غير طاهر، عليه جنابة مثلًا، وكان البرد شديدًا جدًا، ماذا يفعل هذا؟","title":"ما يفعل الجنب إذا كان البرد شديدًا وحضرت الصلاة؟","answer":"الجواب: إذا وجد النار؛ يسخن الماء، يكون في المحل البعيد عن الهواء والبرد، في محل كن، في غرفة، في حمام، ويغتسل، أما إذا كان عليه خطر، ما وجد ماء، أو ماءً باردًا لا يستطيع، ما عنده ما يدفئه به، أو في صحراء، ما عنده ما يتقي به خطر البرد، فيتيمم، مثلما فعل عمرو بن العاص لما اشتد البرد عليه في السفر تيمم، ولم يغتسل من الجنابة. فإذا كان هناك خطر؛ تيمم والحمد لله، أما إن استطاع أن يسخن الماء، وأن يكون في محل كن، في محل مسقوف، محل ما فيه خطر؛ يفعل، هو أعلم بنفسه، هذا يختلف الخطر يختلف. نعم. المقدم: شكر الله لكم يا سماحة الشيخ، وبارك الله فيكم، وفي علمكم، ونفع بكم المسلمين.","link":"https://binbaz.org.sa/fatwas/11642/ما-يفعل-الجنب-اذا-كان-البرد-شديدا-وحضرت-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_523/52313.mp3","categories":["الطهارة لصحة الصلاة"]},{"id":13679,"question":"نختم هذا اللقاء بسؤال للسائل سمير محمد من القصيم يقول: بعدما صليت الفجر في جماعة؛ اكتشفت بأنني جنب، فقمت بالاغتسال، ثم صليت الفجر بعد الاغتسال، فهل صلاتي قبل الاغتسال كانت صحيحة؛ لأنني لم أعرف بأنني جنب؟","title":"حكم صلاة من صلى وعليه جنابة","answer":"الجواب: الصلاة غير صحيحة، مادام علمت أنك جنب، أو على غير طهارة؛ فالصلاة غير صحيحة، لكن صلاة الذين صلوا معك وهم لا يعلمون؛ صلاتهم صحيحة، أما أنت صلاتك غير صحيحة، تعيدها؛ لأنك علمت أنك على حدث، فعليك أن تعيد الصلاة، كما لو صليت وأنت محدث حدثًا أصغر، ثم علمت بعد الصلاة عليك أن تعيد الصلاة، فالجنب، والمحدث حدثًا أصغر عليهما الإعادة إذا صليا على غير طهارة، ثم علما عليهما الإعادة. أما لو كانا إمامين، ولم يعلما إلا بعد الصلاة، فإن صلاة من خلفهم صحيحة، أما هما فعليهما الإعادة، ولو تنبه وهو في الصلاة؛ انفصل منها، واستخلف من يصلي بهم، ويكمل بهم، أو قدم واحدًا، يعني: يقدم واحدًا يصلي بهم، والحمد لله. نعم. المقدم: شكر الله لكم يا سماحة الشيخ، وبارك الله فيكم، وفي علمكم، ونفع بكم المسلمين.","link":"https://binbaz.org.sa/fatwas/12028/حكم-صلاة-من-صلى-وعليه-جنابة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_529/52920.mp3","categories":["الطهارة لصحة الصلاة"]},{"id":14216,"question":"السائل علي خالد يقول: صليت المغرب والعشاء ولم تكن ثيابي طاهرة، هل علي الإعادة في مثل هذه الحالة؟","title":"هل تجب الإعادة على من صلى في ثياب نجسة؟","answer":"الجواب: إذا كنت تعلم أنها نجسة فعليك الإعادة، أما إذا كنت لا تعلم إلا بعد الصلاة لجهل أو نسيان فالصلاة صحيحة، أما إن كنت حين صليت فيها تعلم أنها نجسة فإن الصلاة غير صحيحة، أما لو كنت لا تعلم إلا بعد الصلاة؛ أُخبرت بعد الصلاة أو ذُكِّرت بعد الصلاة فالصلاة صحيحة. نعم.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12667/هل-تجب-الاعادة-على-من-صلى-في-ثياب-نجسة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_548/54817.mp3","categories":["الطهارة لصحة الصلاة","النجاسات وإزالتها"]},{"id":14392,"question":"إذا احتلم شخص، وأصبح جنبًا، ولم يستيقظ من النوم إلا وقد أوشكت الشمس على الطلوع، فهل يصلي وهو جنب لخوفه من ذهاب الوقت، أم يغتسل ثم يؤدي الصلاة؟","title":"هل يصلي الجنب إذا خاف خروج الوقت قبل الغسل؟","answer":"الجواب: إذا استيقظ الإنسان وهو جنب، يبدأ بالغسل، ولا يصلي وهو جنب؛ لقول النبي ﷺ: من نام عن الصلاة أو نسيها فليصليها إذا ذكرها، لا كفارة لها إلا ذلك هذا وقتها، يغتسل ثم يصلي، وليس له الصلاة وهو على الجنابة، سواء قام عند طلوع الشمس أو بعد طلوع الشمس، أو بعد العصر وهو نائم عن العصر، يغتسل ثم يصلي، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12873/هل-يصلي-الجنب-اذا-خاف-خروج-الوقت-قبل-الغسل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_552/55214.mp3","categories":["الطهارة لصحة الصلاة"]},{"id":14916,"question":"أيضًا يقول المرسل من الرياض: إذا تناوم الإنسان في منى، ووجب عليه الماء للغسل، إلا أنه لكثرة الحجاج يقل الماء، فماذا يفعل بدل الماء؟ وكيف إذا أراد أن يصلي وهو عليه جنابة، وكيف يتطهر ويتمم الصلاة إذا صح أن يتطهر بالتراب؟أرجو توضيح هذه المسألة؛ لأن كثيرًا من الناس يقعون في مثل هذا، ولكم منا جزيل الشكر.","title":"حكم من احتلم في منى والماء قليل ويريد أن يصلي","answer":"الجواب: إذا احتلم الإنسان في مزدلفة، أو في أي مكان فيه الناس مع الناس؛ فيلتمس الماء إذا احتلم، يعني: رأى ماءً رأى المني في النوم هذا الاحتلام، يعني: رأى أنه جامع المرأة، أو قام واستيقظ رأى المني خرج من ذكره على فخذيه في سراويله، فهذا يلزمه الغسل غسل الجنابة، فعليه أن يلتمس الماء يطلب الماء، ولو بالشراء في أي مكان يستطيعه، في أطراف منى، في أي جهة، أو يجد محل يغتسل فيه بدون شيء؛ يلزمه ذلك، فإذا لم يتيسر له لا بالثمن، ولا بالتبرع، ما وجد مكان للغسل؛ فإنه يتيمم بالتراب ويصلي، يضرب بيديه التراب ويمسح بهما وجهه وكفيه بنية الجنابة، ونية الحدث الأصغر، يعني: ينوي بالتيمم جميع الحدثين: الحدث الأصغر الذي يوجب الوضوء، والحدث الأكبر الذي يوجب غسل الجنابة، ينويهما جميعًا، وأنه يتيمم حتى يصلي، فيكفيه ذلك ويصلي، وصلاته صحيحة، والحمد لله فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] والله يقول: فَلَمْ تَجِدُوا مَاءً فَتَيَمَّمُوا صَعِيدًا طَيِّبًا فَامْسَحُوا بِوُجُوهِكُمْ وَأَيْدِيكُمْ مِنْهُ [المائدة:6] ولكن عليه أن يجتهد لا يتساهل، يجتهد ويسأل، إذا وجد ماءً ولو بالشراء يأخذ الماء في الصطل ونحوه، فيبتعد عن الناس، بعض الشيء، أو يلتمس خيمة إن كان هناك خيمة، وهي ما فيها أحد، أو في محل بعيد عن أنظار الناس ويغتسل، نعم. السؤال: لكن إذا تعذر مثلًا؟\nالجوب: إذا تعذر يتيمم.\nالمقدم: يتيمم. الشيخ: نعم، والحمد لله.","link":"https://binbaz.org.sa/fatwas/13420/حكم-من-احتلم-في-منى-والماء-قليل-ويريد-ان-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_646/nour_64605.mp3","categories":["الطهارة لصحة الصلاة"]},{"id":14955,"question":"المقدمة حنان العبدالواحد، بعثت بهذه الرسالة تقول فيها: لقد وقع على ثوبي نقط ندم من كبد الإبل، وأنا أقطعها، ولا أعلم بذلك إلا من بعد شفتها، وأنني قد صليت في ثوبي صلاة الظهر والعصر والمغرب، فهل أقضيها أم لا؟جزاكم الله عني خير الجزاء.","title":"هل تعيد الصلاة من أصاب ثيابها دم الإبل دون علمها؟","answer":"الجواب: لا قضاء، ما أصاب الثوب من نقط الدم، ولم تعلميها إلا بعد الصلاة، فلا إعادة على الصحيح، إذا نسي الإنسان النجاسة، أو جهلها في ثوبه، ولم يعلم إلا بعد الصلاة، فلا قضاء عليه على الصحيح من أقوال العلماء؛ لأن النبي ﷺ كان ذات يوم يصلي وفي نعليه أذىً فأخبره جبرائيل -عليه الصلاة والسلام- بأنه فيهما قذرًا؛ فخلعهما ولم يعد أول الصلاة -عليه الصلاة والسلام-، فدل ذلك على أن الصلاة لا تعاد إذا كان هناك نجاسة في نعل أو في ثوب فلم يعلم بها إلا بعد الصلاة، نعم. لكن الحدث لا، إذا كان مثلاً صلى يظنه على طهارة، ثم بان أنه على غير طهارة، فهذا يعيد على كل حال عند جميع أهل العلم، صلى الإنسان أو صلت المرأة تحسب أنها على طهارة، ثم ذكر أو ذكرت أنها حين صلت ليست على طهارة، قد خرج منها بول أو ريح، أو ما أشبه هذا؛ تعيد الصلاة عند جميع أهل العلم، ليس مثل النجاسة، نعم.\nالمقدم: لكن هل يعتبر الدم الواقع من كبد الإبل نجس؟\nالجواب: الأقرب -والله أعلم- أنه ما يعد، ما دام في أثناء الكبد شيء متعلق باللحم ما يعد شيئًا، ما يعد إلا طاهر، هذا هو الأقرب، ما يكون في أثناء اللحم وبعد الذبح في أثناء اللحم في البطن في الكبد في الأمعاء في أشباه ذلك.  المقصود: أن الدم الذي يبقى في اللحوم وفي العروق ما يضر، إنما الذي ينجس ويضر المسفوح الذي عند الذبح، لكن على كل حال لو فرضنا أن بها نجاسة من نقط دم آخر يسمى نجسًا، أو من الدم المسفوح، أو من النجاسات الأخرى من بول أو غيره لم تعلم به إلا بعد الصلاة، فلا إعادة، نعم. المقدم: أثابكم الله.","link":"https://binbaz.org.sa/fatwas/13452/هل-تعيد-الصلاة-من-اصاب-ثيابها-دم-الابل-دون-علمها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_648/nour_64805.mp3","categories":["الطهارة لصحة الصلاة","النجاسات وإزالتها"]},{"id":15091,"question":"المستمع (م. س. أ) من مصر، بعث برسالة ضمنها جمعًا من الأسئلة، في أحدها يقول: ما حكم من اغتسل من الجنابة دون أن يتوضأ في أول الغسل؟ وهل لمن يتوضأ في أول الغسل عليه أن يغسل رجليه أم لا؟","title":"حكم الاكتفاء بغسل الجنابة عن الوضوء","answer":"الجواب: إذا اغتسل من الجنابة ناويًا الحدثين الأكبر والأصغر أجزأ عنهما، أما إذا ما نوى إلا الأكبر فقط، فالذي ينبغي أن يتوضأ، وقد ذهب بعض أهل العلم إلى إجزائه عن الوضوء؛ لأن الأصغر يدخل في الأكبر، ولكن ظاهر الأحاديث خلاف ذلك؛ لقوله ﷺ: إنما الأعمال بالنيات وهو لم ينو إلا الأكبر. فالواجب عليه أن يتوضأ بعد ذلك الوضوء الشرعي. والسنة أن يبدأ بالوضوء، هذا هو السنة، يبدأ بالوضوء، ثم يغتسل، هذا هو السنة، وإذا توضأ قبل ذلك، فإن ترك رجليه، ثم كمل الغسل فلا بأس، وإن كمل رجليه فهو أفضل، وقد ثبت عنه ﷺ هذا وهذا، ثبت عنه في حديث عائشة أنه توضأ، وكمل الوضوء، وثبت عنه في حديث ميمونة أنه ترك الرجلين، حتى فرغ، ثم غسلهما مكانًا آخر. فكونه يتوضأ وضوءًا كاملًا، ثم يغتسل، ثم بعد هذا يغسل رجليه مرة أخرى، يكون هذا أفضل، وإن تركهما حتى كمل الغسل، ثم كملهما، فلا حرج في ذلك؛ لأن الغسل صار الآن مشتركًا بين الوضوء والغسل، فإذا توضأ الوضوء الشرعي إلا الرجلين، ثم كمل غسله، ثم كمل رجليه، فلا حرج، لكن مثلما تقدم كونه يكمل الوضوء حتى الرجلين، ثم يكمل الغسل يكون هذا هو الأفضل، ثم بعد ذلك يغسل قدميه، مكانًا آخر، إذا تيسر ذلك، فإن كان المكان واحدًا، وليس فيه شيء يتعلق بالرجلين، بأن كان مبلطًا، غسلهما في المكان، والحمد لله. وكونه غسلهما في المكان الآخر -عليه الصلاة والسلام- محمول على أن انتقاله من المحل الذي قد يكون علق بهما شيء من طينه وترابه، فيغسلهما في مكان آخر لهذه العلة، هذا هو الظاهر، والله أعلم، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13584/حكم-الاكتفاء-بغسل-الجنابة-عن-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_494/49402.mp3","categories":["الغسل","الطهارة لصحة الصلاة"]},{"id":15150,"question":"سؤاله الأخير يقول: هل الاستحمام يكفي أو يمنع من الوضوء؟أرشدونا في ذلك، جزاكم الله عنا خير الجزاء.","title":"حكم الاكتفاء بالغسل عن الوضوء","answer":"الجواب: السنة أن يتوضأ أولًا وضوء الصلاة كاملًا، أو إلا رجليه، ثم يغتسل للجنابة، ثم يغسل رجليه بعد ذلك إذا كان لم يغسلها، وإن كان قد غسلها، غسلها أيضًا مرة أخرى عملًا بالسنة، هذا إذا كان في الجنابة، وإن نوى الحدثين جميعًا، واغتسل غسلًا كاملًا، ولم يخص الوضوء بأعماله أجزأ عند جمع من أهل العلم، بنيته الحدثين، ولكن الأولى والأفضل والسنة أن يتوضأ وضوء الصلاة، كما فعله النبي ﷺ بعد الاستنجاء، يستنجي يغسل ذكره وما حوله، ويتوضأ وضوء الصلاة، ثم يكمل غسل الجنابة، هذا هو السنة، وهذا هو الأفضل. أما غسل التبرد أو غسل الجمعة؛ فهذا لا يكفي عن الوضوء، لا بد من الوضوء، ثم الغسل، أو الغسل أولًا، ثم الوضوء، نعم.","link":"https://binbaz.org.sa/fatwas/13656/حكم-الاكتفاء-بالغسل-عن-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_658/nour_65808.mp3","categories":["الغسل","الطهارة لصحة الصلاة"]},{"id":15154,"question":"سؤاله الأخير يقول: هل الاستحمام يكفي أو يمنع من الوضوء؟أرشدونا في ذلك، جزاكم الله عنا خير الجزاء.","title":"حكم الاكتفاء بالغسل عن الوضوء","answer":"الجواب: السنة أن يتوضأ أولًا وضوء الصلاة كاملًا، أو إلا رجليه، ثم يغتسل للجنابة، ثم يغسل رجليه بعد ذلك إذا كان لم يغسلها، وإن كان قد غسلها، غسلها أيضًا مرة أخرى عملًا بالسنة، هذا إذا كان في الجنابة، وإن نوى الحدثين جميعًا، واغتسل غسلًا كاملًا، ولم يخص الوضوء بأعماله أجزأ عند جمع من أهل العلم، بنيته الحدثين، ولكن الأولى والأفضل والسنة أن يتوضأ وضوء الصلاة، كما فعله النبي ﷺ بعد الاستنجاء، يستنجي يغسل ذكره وما حوله، ويتوضأ وضوء الصلاة، ثم يكمل غسل الجنابة، هذا هو السنة، وهذا هو الأفضل. أما غسل التبرد أو غسل الجمعة؛ فهذا لا يكفي عن الوضوء، لا بد من الوضوء، ثم الغسل، أو الغسل أولًا، ثم الوضوء، نعم.","link":"https://binbaz.org.sa/fatwas/13656/حكم-الاكتفاء-بالغسل-عن-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_658/nour_65808.mp3","categories":["الغسل","الطهارة لصحة الصلاة"]},{"id":15716,"question":"يقول السائل: يا سماحة الشيخ، إذا صليت دون وضوء ناسيًا، ولم أعلم إلا بعد الفراغ من الصلاة، فماذا أفعل؟","title":"حكم من صلى بغير طهارة ناسيًا","answer":"الجواب: نعم؛ عليك أن تعيد الصلاة إذا كانت فريضة، ولا إثم عليك إذا كنت ناسيًا، عليك أن تعيد؛ لقول النبي ﷺ: لا تقبل صلاة بغير طهور ويقول ﷺ: لا تقبل صلاة أحدكم إذا أحدث حتى يتوضأ. فالمقصود: أن الحدث يبطل الصلاة، فإذا كنت قد أحدثت، ثم صليت ناسيًا فعليك أن تعيد، وهكذا من أحدث في الصلاة، أو خرج منه بول، وهو في الصلاة بطلت صلاته؛ عليه أن يتوضأ، ويعيد الصلاة، نعم.","link":"https://binbaz.org.sa/fatwas/14276/حكم-من-صلى-بغير-طهارة-ناسيا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_574/57406.mp3","categories":["الطهارة لصحة الصلاة"]},{"id":15969,"question":"ماذا يجب على المسلم أن يوفره لصحة الصلاة؟ وكيف يكون حال المسلم في الصلاة؟","title":"ماذا يجب على المسلم لصحة الصلاة؟","answer":"الجواب:   يجب عليه أن يتوضأ إذا كان على غير طهارة، وأن يعد المصلى إذا كان ما عنده أرض طيبة طاهرة، يعد مصلى حصير، سجادة من القطن أو غيره حتى يصلي عليها إذا كان ما عنده محل طاهر يعد السترة التي تستر عورته مثل قميص، إزار ورداء يعد الشيء الواجب عليه في الصلاة، ويستحب له أن يعد سترة يجعلها أمامه، إذا كان ما عند جدار يلتمس كرسي أو حربة يركزها أمامه، سنة الصلاة إلى السترة، نعم. \nالمقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14575/ماذا-يجب-على-المسلم-لصحة-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_746/nour_74616.mp3","categories":["الطهارة لصحة الصلاة"]},{"id":16302,"question":"رسالة من أحد الإخوة المستمعين يقول: هل من يتهاون في طهارته من الحدث الأكبر، أو الحدث الأصغر يكون حكمه كحكم تارك الصلاة أي: كافر؟ وهل يؤثر ذلك في عقد الزواج مع أنه محافظ على الصلوات في أوقاتها، ومع الجماعة؟","title":"حكم من يتهاون في الطهارة من الحدثين","answer":"الجواب: الواجب على المؤمن أن يتقي الله في طهارته، وأن يتوضأ كما أمره الله، ويغتسل كما أمره الله، ولا أظن مسلمًا يتعمد النقص في غسله ووضوئه، وهو يعلم، فإذا كان يتعمد ذلك، ولا يغسل إلا بعض بدنه عن الجنابة، ولا يغسل إلا بعض الأعضاء في الوضوء، فصلاته باطلة، حكمه حكم من لا يصلي، إذا تعمد ذلك، أما إذا قدر أنه قد يقع منه خلل لم يفطن له، هذا لا يضره، ولا يكون حكمه حكم من ترك الصلاة، ولكن يرشد، ويعلم، ويوجه حتى يحتاط في غسله، ووضوئه، وحتى ينتبه لما قد يقع منه. المقصود: أن الواجب على المؤمن والمؤمنة العناية بالغسل، والعناية بالوضوء، وأن يغتسلا كما أمرهما الله، وأن يتوضآ كما أمرهما الله، أما من تعمد التلاعب بالغسل والوضوء، فهذا حكمه حكم من ترك الصلاة، نعوذ بالله، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14993/حكم-من-يتهاون-في-الطهارة-من-الحدثين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_753/nour_753008.mp3","categories":["الطهارة لصحة الصلاة"]},{"id":16800,"question":"من منطقة القصيم الأخت المستمعة (ح. ع. م) تقول: عندما أذهب إلى أحد أقاربي، ويحين وقت الصلاة، ويقدمون ثيابًا خاصة للصلاة، وأصلي بها، وأنا كارهة؛ لأنني أرى الصغير، والكبير يصلي فيها، وتوضع في الأرض، ويكون في هذه الغرفة أطفال، فهل صلاتي صحيحة؟ أم يجب علي إعادتها عندما أعود إلى منزلي؟ مع العلم أنني أجلس أحيانًا أكثر من وقت هناك، أفتونا جزاكم الله خيرًا، وعن جميع المسلمين.","title":"حكم من صلت وشكت في طهارة الثياب","answer":"الجواب: الأصل أيها الأخت في الله، الأصل الطهارة، فإذا قدم أهل البيت لك ثيابًا للصلاة فيها، فالأصل الطهارة، والحمد لله، ودعي عنك الوساوس، والظنون السيئة، وإذا كانت ملابسك كافية؛ صلي في ملابسك، إذا كانت ملابسك التي عندك كافية؛ صلي فيها، وإذا كانت غير كافية، وقدموا لك جلالًا تلبسينه، أو سجادة تصلين عليها؛ فلا حرج في ذلك، والأصل الطهارة، والحمد لله، ودعي عنك الوساوس، والظن السيئ، فإذا كنت رأيت ريبة؛ فاسألي، قولي: هذا سليم، هذا طاهر؟ ما في بأس، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15565/حكم-من-صلت-وشكت-في-طهارة-الثياب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_823/nour_82305.mp3","categories":["النجاسات وإزالتها","الطهارة لصحة الصلاة","قضايا المرأة"]},{"id":16808,"question":"من منطقة القصيم الأخت المستمعة (ح. ع. م) تقول: عندما أذهب إلى أحد أقاربي، ويحين وقت الصلاة، ويقدمون ثيابًا خاصة للصلاة، وأصلي بها، وأنا كارهة؛ لأنني أرى الصغير، والكبير يصلي فيها، وتوضع في الأرض، ويكون في هذه الغرفة أطفال، فهل صلاتي صحيحة؟ أم يجب علي إعادتها عندما أعود إلى منزلي؟ مع العلم أنني أجلس أحيانًا أكثر من وقت هناك، أفتونا جزاكم الله خيرًا، وعن جميع المسلمين.","title":"حكم من صلت وشكت في طهارة الثياب","answer":"الجواب: الأصل أيها الأخت في الله، الأصل الطهارة، فإذا قدم أهل البيت لك ثيابًا للصلاة فيها، فالأصل الطهارة، والحمد لله، ودعي عنك الوساوس، والظنون السيئة، وإذا كانت ملابسك كافية؛ صلي في ملابسك، إذا كانت ملابسك التي عندك كافية؛ صلي فيها، وإذا كانت غير كافية، وقدموا لك جلالًا تلبسينه، أو سجادة تصلين عليها؛ فلا حرج في ذلك، والأصل الطهارة، والحمد لله، ودعي عنك الوساوس، والظن السيئ، فإذا كنت رأيت ريبة؛ فاسألي، قولي: هذا سليم، هذا طاهر؟ ما في بأس، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15565/حكم-من-صلت-وشكت-في-طهارة-الثياب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_823/nour_82305.mp3","categories":["النجاسات وإزالتها","الطهارة لصحة الصلاة","قضايا المرأة"]},{"id":17115,"question":"من أسئلة هذه السائلة: (س. ن) من جدة تقول: سماحة الشيخ! ما حكم حمل الطفل أثناء الصلاة، أو الطواف وهو لابس حفاظة، وفيها نجاسة، ولكنها لم تتعد الملابس الخارجية، وجزاكم الله خيرًا.","title":"حكم حمل الطفل أثناء الصلاة والطواف","answer":"الجواب: النبي ﷺ صلى بـأمامة بنت زينب، وهو يصلي بالناس -عليه الصلاة والسلام- فإذا حمل الطفل في الصلاة عند الحاجة، أو في الطواف لا حرج، فالنبي ﷺ صلى بـأمامة بنت زينب وهي صغيرة، والطفل قد لا يسلم من خروج شيء منه، فإذا لم يكن هناك شيء ظاهر، ومحفظ فلا بأس، الحمد لله. المقدم: أحسن الله إليكم يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/15922/حكم-حمل-الطفل-اثناء-الصلاة-والطواف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_589/58912.mp3","categories":["الطواف بالبيت","السعي","الطهارة لصحة الصلاة"]},{"id":17196,"question":"المستمعة للبرنامج: (ك. ع. س) تقول: هل يجب الوضوء بعد كل استنجاء من الحدث الأصغر؟","title":"حكم الوضوء بعد الحدث الأصغر","answer":"الجواب: يجب الوضوء للصلاة، أو لمس المصحف، أو للطواف إذا كان في مكة، أما إذا أحدث حدثًا أصغر، وليس في نيته صلاة ما عليه وضوء، لو أحدث في الضحى بولًا، أو غائطًا، أو ريحًا ما عليه وضوء، لكن إذا حضرت الظهر يتوضأ، أو أحدث بعد الظهر، ليس عليه وضوء، فإذا جاء وقت العصر توضأ للعصر.. وهكذا، الوضوء لموجباته؛ للصلاة، أو لمس المصحف، أو للطواف، أو عند إرادة النوم إذا أراد أن ينام، يتوضأ حتى ينام على طهارة، هذا هو المشروع. أما كونه يحدث في الضحى ما يلزمه الوضوء، يستنجي من البول والغائط ويكفي، أو بعد الظهر يستنجي ويكفي، فإذا حضرت الصلاة توضأ. نعم.","link":"https://binbaz.org.sa/fatwas/16015/حكم-الوضوء-بعد-الحدث-الاصغر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_590/59024.mp3","categories":["الطهارة لصحة الصلاة"]},{"id":17199,"question":"السائلة: (ن. ع. م) من الجنوب، تقول سماحة الشيخ: تذكر بأنها معلمة تقوم بإمامة الطالبات في الصلاة، ويصلون في ساحة المدرسة، علمًا بأنها تكون متسخة -أي: غير نظيفة يا شيخ- وذلك من إفطار الطالبات، ويصلون على بعض البسط، ولكنها أيضًا تكون غير نظيفة بالتراب، وقد أخبرت المدرسة بذلك، ولكن لم يتم التغيير؛ نظرًا لعدم وجود إمكانية في ذلك، فما حكم -تقول- صلاتنا؟ وما حكم ذلك لصلاة الطالبات؟ مأجورين.","title":"حكم الصلاة على الفراش المتسخ","answer":"الجواب: لا حرج في ذلك، كونها تأمهن حتى يتعلمن، ويستفدن من صلاتها لا بأس بذلك، ولا بأس بالصلاة على فرش، وإن كانت غير نظيفة، مادام ما فيها نجاسة، وجود التراب عليها، أو بعض الأوراق، أو شيء ما يضر، إذا كانت الأرض طاهرة، والبسط طاهرة، ولو كان فيها بعض الأوساخ لا يضر، يصلى عليها، والطالبات يستفدن من المعلمة إذا صلت بهن، تكون في وسطهن، الإمامة تكون في الوسط؛ في وسط البنات، والنساء. نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16021/حكم-الصلاة-على-الفراش-المتسخ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_590/59027.mp3","categories":["النجاسات وإزالتها","الطهارة لصحة الصلاة","قضايا المرأة"]},{"id":17548,"question":"إذا كان الإنسان جنبًا، فوجد ماء يكفي للوضوء فقط ولا يكفي للغسل، فهل يجوز الوضوء؟","title":"ما يفعل الجنب إذا لم يجد ماء يكفيه للغسل؟","answer":"الجواب: نعم يلزمه الوضوء ويتيمم للباقي؛ لقول الله : فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]، وقول النبي ﷺ: إذا أمرتكم بأمر فأتوا منه ما استطعتم، فإذا كان في السفر أو في محل مسجون فيه لا يستطيع الخروج منه للغسل وعنده ماء قدر الوضوء يتوضأ ويتيمم، وهكذا لو كان في برد شديد وليس عنده ما يدفئ الماء ويخشى من الغسل فإنه يتوضأ إذا استطاع الوضوء ويتيمم، كما فعل عمرو بن العاص  في بعض أسفاره، لما اشتد بهم البرد توضأ وتيمم خوفًا من مضرة الماء.\nفالمقصود أن الإنسان إذا خاف من مضرة الماء لشدة البرد وليس عنده ما يدفئ به الماء وليس عنده محل أيضًا يناسب للغسل فإنه يتيمم ويتوضأ؛ لأنه يقدر على الوضوء، فهكذا الذي ما عنده إلا ماء قليل يستطيع أن يتوضأ منه يتوضأ ويتيمم لبقية الغسل. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16470/ما-يفعل-الجنب-اذا-لم-يجد-ماء-يكفيه-للغسل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_838/nour_83804.mp3","categories":["الطهارة لصحة الصلاة"]},{"id":17554,"question":"إذا كان الإنسان جنبًا، فوجد ماء يكفي للوضوء فقط ولا يكفي للغسل، فهل يجوز الوضوء؟","title":"ما يفعل الجنب إذا لم يجد ماء يكفيه للغسل؟","answer":"الجواب: نعم يلزمه الوضوء ويتيمم للباقي؛ لقول الله : فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]، وقول النبي ﷺ: إذا أمرتكم بأمر فأتوا منه ما استطعتم، فإذا كان في السفر أو في محل مسجون فيه لا يستطيع الخروج منه للغسل وعنده ماء قدر الوضوء يتوضأ ويتيمم، وهكذا لو كان في برد شديد وليس عنده ما يدفئ الماء ويخشى من الغسل فإنه يتوضأ إذا استطاع الوضوء ويتيمم، كما فعل عمرو بن العاص  في بعض أسفاره، لما اشتد بهم البرد توضأ وتيمم خوفًا من مضرة الماء.\nفالمقصود أن الإنسان إذا خاف من مضرة الماء لشدة البرد وليس عنده ما يدفئ به الماء وليس عنده محل أيضًا يناسب للغسل فإنه يتيمم ويتوضأ؛ لأنه يقدر على الوضوء، فهكذا الذي ما عنده إلا ماء قليل يستطيع أن يتوضأ منه يتوضأ ويتيمم لبقية الغسل. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16470/ما-يفعل-الجنب-اذا-لم-يجد-ماء-يكفيه-للغسل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_838/nour_83804.mp3","categories":["الطهارة لصحة الصلاة"]},{"id":17684,"question":"من أسئلة هذا السائل يقول: ما حكم الصلاة على الوضوء لمدة طويلة مثال ذلك يا سماحة الشيخ: يكون المسلم متوضئ لصلاة الفجر، فهل يجوز له أن يصلي بهذا الوضوء صلاة الظهر والعصر والمغرب والعشاء على نفس الوضوء بدون حدث طيلة اليوم؟","title":"حكم أداء الصلوات الخمس بوضوء واحد","answer":"الجواب: إذا لم يحدث فلا بأس، النبي ﷺ يوم الفتح صلى الصلوات كلها بوضوء واحد يوم فتح مكة، سأله عمر عن ذلك قال: عمدًا فعلت ليعلم الناس أنه لا بأس بهذا فإذا توضأ للظهر وصلى بالوضوء الظهر والعصر والمغرب والعشاء ما أحدث فلا بأس به، الحمد لله. نعم.\nالمقدم: الحمد لله أحسن الله إليكم وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/16623/حكم-اداء-الصلوات-الخمس-بوضوء-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_595/59513.mp3","categories":["الطهارة لصحة الصلاة"]},{"id":17835,"question":"السائل محمد أحمد من اليمن يقول: ما قول العلماء في سلس البول إذا حدث أثناء الصلاة هل يبطلها...الشيخ: أعد.المقدم: يقول: ما قول العلماء في مرض سلس البول إذا حدث أثناء الصلاة هل يبطلها؟ وهل يعيد الإنسان الوضوء كاملًا؟ أو يغسل موضع النجاسة فقط؟","title":"سلسل البول إذا حدث أثناء الصلاة هل يبطلها؟","answer":"الجواب: السلس مرض من الأمراض، الذي يصاب بالسلس في البول أو بالريح دائمًا هذا يلزمه أن يتوضأ لكل صلاة مثلما قال النبي ﷺ للمستحاضة التي معها الدم دائمًا: توضئي لوقت كل صلاة فإذا دخل الوقت توضأ وصلى على حسب حاله ولو خرج البول ما دام في الوقت يصلي، ويقرأ القرآن من المصحف، يصلي الفريضة والنافلة ما دام الوقت، فإذا خرج الوقت بطل وضوءه، وعليه أن يتوضأ وضوءًا آخر للصلاة الجديدة. وإذا كان بول أو غائط لا بد يستنجي عن البول والغائط، ثم يتوضأ في أطرافه، يغسل وجهه، يتمضمض ويستنشق، ويغسل وجهه وذراعيه مع المرفقين، ويمسح رأسه مع أذنيه، ويغسل قدميه مع الكعبين. أما إذا كان ريح أحدث بريح، أو مس فرجه، أو نوم فهذا يكفيه الوضوء .... ما يحتاج استنجاء بل يكفي غسل الأطراف الأربعة، يغسل وجهه وذراعيه، ويمسح رأسه ويغسل رجليه عن النوم، والريح، ومس الفرج، وأكل لحم الإبل ما يحتاج استنجاء، الاستنجاء من البول والغائط، إذا حصل بول أو غائط يستنجي يغسل فرجه، ويغسل دبره من الأذى، أو يستجمر بثلاثة أحجار فأكثر حتى ينقي المحل أو يجمع بينهما، يستجمر ويستعمل الماء كل هذا طيب.\nولا يلزمه هذا فيما يتعلق بالريح؛ الفساء، والضراط، هذا إذا خرج منه فساء أو ضراط ما فيه إلا الوضوء يعني: غسل الأطراف الأربعة، ما فيه استنجاء، هكذا إذا مس فرجه بيده، أو أكل لحم الإبل، أو نام نومًا يزول معه عقله نومًا مستغرق ينتقض وضوءه، وعليه الوضوء الذي هو غسل الأطراف الأربعة ما فيه استنجاء.\nأما صاحب السلس فإنه يتوضأ كل وقت إذا كان حدثه دائمًا، معه الريح دائم، معه البول دائم، هذا يتوضأ كل صلاة، كلما أذن يتوضأ، إن كان هناك بول أو غائط يستنجي، فإن كان ريح الريح معه دائم يتوضأ أطرافه فقط، يعني: يتمضمض ويستنشق، ويغسل وجهه، وذراعيه مع المرفقين، ثم يمسح رأسه مع أذنيه، ثم يغسل رجليه عن الريح ما فيها استنجاء، ولحم الإبل مثلًا، النوم المستغرق، مس الفرج. نعم.\nالمقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16828/سلسل-البول-اذا-حدث-اثناء-الصلاة-هل-يبطلها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_779/nour_77908.mp3","categories":["صلاة المريض","الطهارة لصحة الصلاة"]},{"id":17967,"question":"يقول: هناك جماعة يشتغلون في ورشة لإصلاح السيارات وإذا حان موعد الصلاة ذهبوا إلى المسجد بملابس الشغل وتكون ملابسهم متسخة بطبيعة الحال بالزيوت والبويا والمعجون وما أشبه ذلك، فبماذا توجهونهم؟ جزاكم الله خيرًا.","title":"حكم الصلاة بملابس العمل المتسخة","answer":"الجواب: الصلاة صحيحة ولا حرج عليهم، ولكن الأفضل أن يلبسوا، أن يعدوا للصلاة لباسًا حسنًا لقول الله سبحانه: يَا بَنِي آدَمَ خُذُوا زِينَتَكُمْ عِنْدَ كُلِّ مَسْجِدٍ [الأعراف:31]، وقول النبي ﷺ: إن الله جميل يحب الجمال؛ ولئلا يتقذر منه إخوانه؛ ولئلا يؤذي من يجاوره بهذه الملابس، فالسنة لهم والذي أنصحهم به أن يلبسوا ملابس حسنة للصلاة، يعدوها فإذا جاء وقت الصلاة خلعوا هذه الملابس ولبسوا الملابس الحسنة، هذا هو الذي أنصحهم به. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16997/حكم-الصلاة-بملابس-العمل-المتسخة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_848/nour_84806.mp3","categories":["الطهارة لصحة الصلاة"]},{"id":18877,"question":"أرجو الاطلاع على مسألتي هذه، والإجابة عليها؛ حيث أنني أسأل عن الحكم في لو كان شخص في مكان لا يوجد به ماء كافٍ للغسل من الجنابة، ووجد شيئًا قليلًا، ما الحكم؟أرجو إرشادي، جزاكم الله خيرًا.","title":"حكم الجنب الذي لا يجد ماءً كافيًا للغسل","answer":"الجواب: يقول الله سبحانه: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] ويقول النبي ﷺ: إذا أمرتكم بأمر؛ فأتوا منه ما استطعتم فإذا كان الإنسان في مكان ليس فيه إلا ماء قليل لا يكفي للغسل؛ فإنه يغسل به ما أمكن من جسده، ثم يتيمم للباقي؛ لأنه معذور، كالذي في البرية، أو في سجن لا يعطى ماءً إلا لشربه، وليس عنده ماء يكفيه للغسل، ولا يعطى ماء للغسل؛ فإنه يغتسل بالذي عنده، فيغسل بعض بدنه -كرأسه وصدره ونحو ذلك- ويستنجي منه، ويتيمم للباقي، يعني: يضرب التراب بيديه بنية الطهارة، ويسمح بهما وجهه وكفيه عن بقية بدنه، ناويًا بذلك الطهارة من الجنابة، وإن نوى الطهارة من الجنابة وجميع الأحداث صح ذلك، وصارت طهارته كاملة عن الحدث الأكبر والأصغر جميعًا، عملًا بقوله سبحانه: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]. وإذا كان الماء الذي عنده يحتاجه للشرب، ويخشى من العطش؛ فإنه لا يغتسل به، بل يتيمم عن الجميع، ويبقى الماء عنده لحاجته؛ عملًا بقوله سبحانه: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] وعملًا بقوله : وَلا تُلْقُوا بِأَيْدِيكُمْ إِلَى التَّهْلُكَةِ [البقرة:195] نعم.","link":"https://binbaz.org.sa/fatwas/18021/حكم-الجنب-الذي-لا-يجد-ماء-كافيا-للغسل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_880/nour_88003.mp3","categories":["الغسل","الطهارة لصحة الصلاة"]},{"id":18987,"question":"يسأل ويقول: أنا أعمل مكانيكي، ماذا أعمل إذا حضرتني الصلاة وأنا في العمل؟ هل لي أن أصلي بملابس العمل؟ وملابس العمل هذه فيها زيت وقاز، وبعض الناس يقولون: لا تجوز فيها الصلاة، ولا يتسع لي الوقت بتبديلها، ماذا أعمل، وأنا أريد صلاة الجماعة أفيدونا أفادكم الله؟","title":"حكم الصلاة بملابس لها رائحة كريهة","answer":"الجواب: الواجب عليك أن تصلي مع إخوانك المسلمين في الجماعة؛ لقول النبي ﷺ: من سمع النداء فلم يأت فلا صلاة له إلا من عذر، قيل لابن عباس : ما هو العذر؟ قال: خوف أو مرض». ولأنه عليه الصلاة والسلام لما أتاه رجل أعمى يسأله ويقول له: يا رسول الله! ليس لي قائد يقودني للمسجد، فهل لي من رخصة أن أصلي في بيتي؟ فقال له عليه الصلاة والسلام: هل تسمع النداء بالصلاة؟ قال: نعم، قال: فأجب، فهذا أعمى ليس له قائد ومع هذا يأمره أن يجيب المؤذن ويحضر الصلاة. وعليك يا أخي! أن تغير الملابس التي يتأذى منها إخوانك إذا كان فيها رائحة تؤذيهم، أما إذا كان لا تؤذيهم ما فيها رائحة تؤذيهم، فصل فيها، والحمد لله؛ لأنها طاهرة، أما إن كان فيها روائح تؤذيهم، أو أوساخ تنتقل إليهم إلى من بجوارك، تنتقل إليه الأوساخ فلا، بدلها، أعد الثياب إذا أذن المؤذن تلبسها، وتذهب إلى الصلاة. وعليك أن تتقي الله في ذلك، هذا أمر عظيم، هذه عمود الإسلام، الصلاة عمود الإسلام، فلا بد من العناية بها، أعظم واجب، وأهم واجب بعد الشهادتين هذه الصلاة، يقول فيها النبي ﷺ: رأس الأمر الإسلام، وعموده الصلاة ويقول فيها عليه الصلاة والسلام: من حافظ عليها كانت له نورًا، وبرهانًا، ونجاة يوم القيامة، ومن لم يحافظ عليها لم يكن له نور، ولا برهان، ولا نجاة، وحشر يوم القيامة مع فرعون، وهامان، وقارون، وأبي بن خلف. وهذا وعيد عظيم يحشر من تركها مع هؤلاء الكفرة؛ لأنه إن ضيعها من أجل الرياسة والملك، صار شبيهًا بفرعون والعياذ بالله، فيحشر معه إلى النار يوم القيامة. وإن ضيعها بسبب الوزارة والوظيفة صار شبيهًا بهامان وزير فرعون ، فيحشر معه إلى النار يوم القيامة. وإن ضيعها بأسباب المال والشهوات صار شبيهًا بقارون تاجر بني إسرائيل الذي حمله كبره وبغيه على ترك الحق، فيحشر معه إلى النار يوم القيامة. وإن ترك الصلاة من أجل التجارة والبيع والشراء صار شبيهًا بأبي بن خلف تاجر أهل مكة، الذي قتله النبي ﷺ يوم أحد كافرًا، فيحشر معه إلى النار يوم القيامة. فالواجب على العامل ميكانيكي أو غيره الواجب عليه أن يصلي مع المسلمين في الجماعة، وأن يلبس الملابس التي لا تؤذي الناس الطيبة السليمة، ويبتعد عن الروائح الكريهة إذا كان يتعاطى الثوم، أو البصل، أو التدخين، يحذر ذلك، حتى لا يكون فيه روائح كريهة وقت الصلاة، وحتى لا تكون في ملابسه أوساخ تؤذي الناس، أما إن كان لا تؤذي الناس فلا بأس أن يصلي فيها إذا كانت طاهرة. ولكن كونه يلبس ثيابًا حسنة وجميلة للصلاة هذا هو الأفضل يقول الله سبحانه: يَا بَنِي آدَمَ خُذُوا زِينَتَكُمْ عِنْدَ كُلِّ مَسْجِدٍ[الأعراف:31] يعني عند كل صلاة، فالمشروع للمؤمن عند الصلاة أنه يلبس الملابس الحسنة، يتوجه للمسجد بالملابس الحسنة مع إخوانه، لأنه يقوم بين يدي الله، نسأل الله للجميع التوفيق. نعم. المقدم: اللهم آمين، جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/18152/حكم-الصلاة-بملابس-لها-راىحة-كريهة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_793/nour_79305.mp3","categories":["الطهارة لصحة الصلاة"]},{"id":19028,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات تقول في نهايتها: المرسلة (ح.ع.خ) أختنا لها قضية تقول فيها: إذا ذهبنا إلى أحد أقاربنا وحان وقت الصلاة، فإننا نصلي عندهم بثياب خاصة للصلاة، وقد نصلي ونحن كارهون هذه الثياب؛ لأننا نشك في طهارتها، والله أعلم بطهارة الأرض - أيضًا - التي نمشي عليها، ونحن نصلي فيها كذلك.هل صلاتنا صحيحة أم لا؟ وإذا كان علينا الإعادة إذا عدنا للمنزل فإننا نصلي أحيانًا أكثر من وقت عندهم، جزاكم الله خيرًا.","title":"حكم صلاة من شك في طهارة الأرض والثياب","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله، وأصحابه، ومن اهتدى بهداه، أما بعد: فالأصل في الثياب، وفي الأرض، وفي كل شيء؛ الأصل فيه الطهارة، إلا ما علمت نجاسته، فإذا كانت الثياب التي صليتم فيها لا تعلمون نجاستها فالصلاة صحيحة، والشك لا يعتبر، ولا يلتفت إليه، وهكذا الأرض الأصل فيها الطهارة، فإذا كنتم لا تعلمون نجاستها فالأصل الطهارة، وليس عليكم إعادة، والحمد لله. نعم. المقدم: جزاكم الله خيرًا، إذًا لا داعي للشك في هذا ... ؟ الشيخ: هذا من الشيطان، هذا من الشيطان. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18195/حكم-صلاة-من-شك-في-طهارة-الارض-والثياب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_796/nour_79601.mp3","categories":["الطهارة لصحة الصلاة"]},{"id":19272,"question":"عندما أتذكر أنني صليت ذات مرة على غير وضوء، هل أعيد تلك الصلاة؟","title":"حكم من تذكر أنه صلى مرة بغير وضوء","answer":"الجواب: نعم، تجب الإعادة بإجماع المسلمين؛ لقول النبي ﷺ: لا تقبل صلاة بغير طهور، رواه مسلم في الصحيح، ولقوله ﷺ: لا تقبل صلاة أحدكم إذا أحدث حتى يتوضأ، متفق على صحته. نعم.","link":"https://binbaz.org.sa/fatwas/18460/حكم-من-تذكر-انه-صلى-مرة-بغير-وضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_892/nour_89206.mp3","categories":["الطهارة لصحة الصلاة"]},{"id":19633,"question":"المستمعة أم محمد تقول: امرأة بعد تغسيل أطفالها من النجاسة يأتيها رذاذ ماء، فهل يعتبر نجس أم لا؟","title":"حكم رذاذ الماء المتطاير عند تغسيل الأطفال من النجاسة","answer":"الجواب: إذا كان فيه النجاسة قبل أن تطهر من النجاسة يكون نجس، أما إذا كان قد زالت النجاسة من أبنائها فيكون طاهر، فعليها التحرز عند غسل الطفل، أو ثيابه؛ تتحرز حتى لا يأتيها شيء من النجاسة. نعم.","link":"https://binbaz.org.sa/fatwas/18900/حكم-رذاذ-الماء-المتطاير-عند-تغسيل-الاطفال-من-النجاسة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_948/nour_94831.mp3","categories":["النجاسات وإزالتها","الطهارة لصحة الصلاة","قضايا المرأة"]}]
